        BigDecimal price = new BigDecimal(s.next());
        BigDecimal rate = new BigDecimal(s.next()).movePointLeft(2);
        int count = s.nextInt();
        BigDecimal total = price.multiply(BigDecimal.valueOf(count)).multiply(BigDecimal.ONE.add(rate)).setScale(2, RoundingMode.HALF_UP);
        System.out.println(total);
    }
}

